+function setTheme([theme, underlineLinks]) {
+    if (theme === THEME_OS) {
+        theme = osDarkTheme.matches ? THEME_DARK : THEME_LIGHT;
+    }
+    document.documentElement.setAttribute("data-" + THEME, theme);
+    if (underlineLinks) {
+        document.documentElement.setAttribute("data-" + UNDERLINE_LINKS, underlineLinks);
+    } else {
+        document.getElementById(UNDERLINE_LINKS).checked = (theme === THEME_DARK);
+    }
